package net.nuggetmc.tplus.compat.bukkit.event.entity;
import java.util.*; import net.nuggetmc.tplus.compat.bukkit.event.*; import net.nuggetmc.tplus.compat.bukkit.entity.LivingEntity; import net.nuggetmc.tplus.compat.bukkit.inventory.ItemStack;
public class EntityDeathEvent extends Event { private final LivingEntity entity; private final Object damageSource; private final List<ItemStack> drops; private int exp; public EntityDeathEvent(LivingEntity e,Object source,List<ItemStack> drops,int exp){entity=e;damageSource=source;this.drops=drops==null?new ArrayList<>():drops;this.exp=exp;} public LivingEntity getEntity(){return entity;} public Object getDamageSource(){return damageSource;} public List<ItemStack> getDrops(){return drops;} public int getDroppedExp(){return exp;} public void setDroppedExp(int e){exp=e;} }
